var orders = new List<int> { 40, 75, 120 }; // order totals, like a table
var calls = 0;

IEnumerable<int> toExport = orders.Where(total =>
{
    calls++;                 // counts every filter call
    return total > 50;
});

Console.WriteLine(toExport.Count()); // 2: logged as "Exporting 2 orders"
orders.Add(300);                     // a new order arrives meanwhile
foreach (var total in toExport)
{
    Console.WriteLine(total);        // 75, 120, 300: three rows written
}
Console.WriteLine(calls);            // 7: the filter ran on both passes

var orders = new List<int> { 40, 75, 120 }; // order totals, like a table
var calls = 0;

List<int> toExport = orders.Where(total =>
{
    calls++;                 // counts every filter call
    return total > 50;
}).ToList();                 // run the query once, keep the results

Console.WriteLine(toExport.Count);   // 2: logged as "Exporting 2 orders"
orders.Add(300);                     // goes into the next export
foreach (var total in toExport)
{
    Console.WriteLine(total);        // 75, 120: two rows written
}
Console.WriteLine(calls);            // 3: one pass over three orders
